// --- GLOBAL HELPER: Formatting Currency based on Toggle ---
        function formatCurrency(num, hideDecimals = true) {
            const currency = document.getElementById('global-currency').value;
            let locale = 'en-US';
            if (currency === 'INR') locale = 'en-IN';
            if (currency === 'GBP') locale = 'en-GB';
            if (currency === 'EUR') locale = 'de-DE';
            const opts = { style: 'currency', currency: currency };
            if (hideDecimals) { opts.maximumFractionDigits = 0; }
            return num.toLocaleString(locale, opts);
        }
        // --- 1. LTV & CAC Engine ---
        function calculateLTVCAC() {
            const avgRev = parseFloat(document.getElementById('ltv-avg-rev').value) || 0;
            const projects = parseFloat(document.getElementById('ltv-projects').value) || 1;
            const marginPct = (parseFloat(document.getElementById('ltv-margin').value) || 0) / 100;
            const currentCac = parseFloat(document.getElementById('ltv-current-cac').value) || 0;
            const ltv = avgRev * projects;
            const maxCac = ltv * (1 - marginPct);
            document.getElementById('ltv-result').textContent = formatCurrency(ltv);
            document.getElementById('cac-max-result').textContent = formatCurrency(maxCac);
            const statusEl = document.getElementById('cac-status');
            if (currentCac > maxCac) {
                statusEl.textContent = `Warning: Current CAC (${formatCurrency(currentCac)}) destroys your target margin.`;
                statusEl.className = "text-xs font-bold text-rose-600 mt-1";
            } else {
                statusEl.textContent = `Current CAC (${formatCurrency(currentCac)}) is profitable within your margin.`;
                statusEl.className = "text-xs font-bold text-emerald-600 mt-1";
            }
        }
        // --- 2. Client Concentration Risk Analyzer ---
        function calculateConcentrationRisk() {
            const totalRev = parseFloat(document.getElementById('risk-total-rev').value) || 1;
            const topClientRev = parseFloat(document.getElementById('risk-top-client').value) || 0;
            const riskPct = (topClientRev / totalRev) * 100;
            const resEl = document.getElementById('risk-pct-result');
            const diagEl = document.getElementById('risk-diagnosis');
            resEl.textContent = riskPct.toFixed(1) + '%';
            if (riskPct >= 40) {
                resEl.className = "font-mono text-4xl font-black text-rose-600";
                diagEl.textContent = "Critical Risk: Losing this client jeopardizes your solvency.";
                diagEl.className = "text-xs font-bold text-rose-600";
            } else if (riskPct >= 20) {
                resEl.className = "font-mono text-4xl font-black text-amber-600";
                diagEl.textContent = "Moderate Risk: Aggressively diversify acquisition channels.";
                diagEl.className = "text-xs font-bold text-amber-600";
            } else {
                resEl.className = "font-mono text-4xl font-black text-emerald-600";
                diagEl.textContent = "Healthy: Highly diversified, low concentration risk.";
                diagEl.className = "text-xs font-bold text-emerald-600";
            }
        }
        // --- 3. PPP Pricing Engine ---
        function calculatePPP() {
            const baseRate = parseFloat(document.getElementById('ppp-base-rate').value) || 0;
            const multiplier = parseFloat(document.getElementById('ppp-client-region').value) || 1;
            const localizedRate = baseRate * multiplier;
            document.getElementById('ppp-result-rate').textContent = formatCurrency(localizedRate);
        }
        // --- 4. Scope Creep Quantifier ---
        function calculateScopeCreep() {
            const fee = parseFloat(document.getElementById('creep-fee').value) || 0;
            const estHours = parseFloat(document.getElementById('creep-est-hours').value) || 1;
            const actHours = parseFloat(document.getElementById('creep-act-hours').value) || 1;
            const targetRate = fee / estHours;
            const actualRate = fee / actHours;
            let dilution = 0;
            if (targetRate > 0) dilution = ((actualRate - targetRate) / targetRate) * 100;
            document.getElementById('creep-target-rate').textContent = formatCurrency(targetRate, false) + '/hr';
            document.getElementById('creep-actual-rate').textContent = formatCurrency(actualRate, false) + '/hr';
            const dilutionEl = document.getElementById('creep-dilution-pct');
            dilutionEl.textContent = dilution.toFixed(1) + '%';
            if (dilution < 0) { dilutionEl.className = "text-xl font-black text-rose-700"; }
            else if (dilution > 0) { dilutionEl.textContent = '+' + dilution.toFixed(1) + '%'; dilutionEl.className = "text-xl font-black text-emerald-600"; }
            else { dilutionEl.className = "text-xl font-black text-slate-700"; }
        }
        // --- 5. AI Delegation ROI Engine ---
        function calculateAIRoi() {
            const rate = parseFloat(document.getElementById('ai-rate').value) || 0;
            const cost = parseFloat(document.getElementById('ai-cost').value) || 0;
            const hours = parseFloat(document.getElementById('ai-hours').value) || 0;
            const gainPct = (parseFloat(document.getElementById('ai-gain').value) || 0) / 100;
            const valueOfTimeSaved = (hours * gainPct) * rate;
            const netProfit = valueOfTimeSaved - cost;
            const resElement = document.getElementById('ai-roi-result');
            resElement.textContent = formatCurrency(netProfit);
            resElement.className = netProfit < 0 ? "font-mono text-3xl font-bold text-rose-600" : "font-mono text-3xl font-bold text-cyan-900";
        }
        // --- 6. The Zoom Tax Meeting Calculator ---
        function calculateMeetingCost() {
            const myRate = parseFloat(document.getElementById('meet-my-rate').value) || 0;
            const clientRate = parseFloat(document.getElementById('meet-client-rate').value) || 0;
            const attendees = parseFloat(document.getElementById('meet-attendees').value) || 1;
            const durationMins = parseFloat(document.getElementById('meet-duration').value) || 0;
            const clientTeamCost = (attendees > 1 ? (attendees - 1) : 0) * clientRate;
            const totalHourlyRate = myRate + clientTeamCost;
            const totalMeetingCost = totalHourlyRate * (durationMins / 60);
            document.getElementById('meet-total-cost').textContent = formatCurrency(totalMeetingCost);
        }
        // --- 7. Creator Revenue Logic ---
        function calculateCreatorRevenue() {
            const views = parseFloat(document.getElementById('creator-views').value) || 0;
            const niche = document.getElementById('creator-niche').value;
            let rpm, cpv;
            switch (niche) {
                case 'finance': rpm = 12.00; cpv = 0.035; break;
                case 'lifestyle': rpm = 6.00; cpv = 0.020; break;
                case 'gaming': rpm = 3.00; cpv = 0.010; break;
                default: rpm = 5.00; cpv = 0.020;
            }
            const adsense = (views / 1000) * rpm;
            const integration = views * cpv;
            const dedicated = integration * 2.5;
            document.getElementById('res-adsense').textContent = formatCurrency(adsense);
            document.getElementById('res-integration').textContent = formatCurrency(integration);
            document.getElementById('res-dedicated').textContent = formatCurrency(dedicated);
        }
        // --- 8. Hourly Rate Logic ---
        function calculateRate() {
            const annual = parseFloat(document.getElementById('target-income').value) || 0;
            const overhead = (parseFloat(document.getElementById('overhead').value) || 0) * 12;
            const hours = parseFloat(document.getElementById('billable-hours').value) || 1;
            const weeksOff = parseFloat(document.getElementById('weeks-off').value) || 0;
            const totalTarget = (annual + overhead) / 0.7;
            const workingWeeks = 52 - weeksOff;
            const totalHours = hours * workingWeeks;
            const rate = totalHours > 0 ? totalTarget / totalHours : 0;
            document.getElementById('rate-result').textContent = formatCurrency(rate);
        }
        // --- 9. Global Tier-1 Tax Estimator Logic ---
        function calculateTaxes() {
            const amount = parseFloat(document.getElementById('gig-amount').value) || 0;
            const region = document.getElementById('tax-region').value;
            const container = document.getElementById('tax-breakdown-container');
            let net = amount;
            let breakdownHTML = '';
            const addRow = (label, value, isDeduction = true) => {
                const color = isDeduction ? 'text-red-500' : 'text-slate-600';
                const sign = isDeduction ? '-' : '';
                breakdownHTML += `
                <div class="flex justify-between items-center p-3 bg-white rounded-lg border border-slate-100">
                    <span class="text-sm font-medium text-slate-600">${label}</span>
                    <span class="font-mono ${color} font-bold">${sign}${formatCurrency(value)}</span>
                </div>`;
                if (isDeduction) net -= value;
            };
            if (amount > 0) {
                switch (region) {
                    case 'us': addRow('Est. Federal/State Income (20%)', amount * 0.20); addRow('Self-Employment Tax (15.3%)', amount * 0.153); break;
                    case 'uk': addRow('Est. Income Tax (20%)', amount * 0.20); addRow('National Insurance Class 4 (9%)', amount * 0.09); break;
                    case 'ca': addRow('Federal + Provincial Avg (25%)', amount * 0.25); addRow('CPP Contribution (11.9%)', amount * 0.119); break;
                    case 'au': addRow('Income Tax Est (32.5%)', amount * 0.325); addRow('Medicare Levy (2%)', amount * 0.02); break;
                    case 'in': addRow('TDS / Income Tax Est (10%)', amount * 0.10); addRow('GST Obligation (18%)', amount * 0.18); break;
                    default: addRow('Global Standard Reserve (20%)', amount * 0.20);
                }
            }
            container.innerHTML = breakdownHTML;
            document.getElementById('net-keep').textContent = formatCurrency(Math.max(0, net));
        }
        // --- 10. Risk Scanner Logic ---
        function scanForRedFlags() {
            const text = document.getElementById('red-flag-text').value.toLowerCase();
            const flags = [
                { term: 'simple job', risk: 'High', msg: 'Implicit scope creep. Projects labeled "simple" usually lack clear requirements.' },
                { term: 'exposure', risk: 'Critical', msg: 'Non-monetary payment alert. Exposure does not pay operational overhead.' },
                { term: 'quick', risk: 'Medium', msg: 'Expect unrealistic timelines. A rush fee buffer may be required.' },
                { term: 'partnership', risk: 'High', msg: 'Equity often means zero immediate capital. Verify funding.' },
                { term: 'cheap', risk: 'High', msg: 'Price shopping alert. The client will likely undervalue your professional input.' }
            ];
            let found = flags.filter(f => text.includes(f.term));
            const res = document.getElementById('risk-result');
            res.classList.remove('hidden');
            if (found.length > 0) {
                res.className = 'mt-4 p-4 rounded-xl border border-red-100 bg-red-50 text-red-800 text-sm leading-relaxed';
                res.innerHTML = `<strong>Warning: Risk Level - ${found[0].risk}</strong><br><ul class="mt-2 list-disc pl-5">${found.map(f => '<li>' + f.msg + '</li>').join('')}</ul>`;
            } else if (text.length > 10) {
                res.className = 'mt-4 p-4 rounded-xl border border-emerald-100 bg-emerald-50 text-emerald-800 text-sm';
                res.innerHTML = "<strong>Clear: Risk Level - Low</strong><br>No obvious red flag semantics detected in the text.";
            } else {
                res.classList.add('hidden');
            }
        }
        // --- 11. Dynamic Contract Generator & PDF Logic ---
        // Add Dynamic Party
        function addPartyBlock(role = '', name = '', isRemovable = true) {
            const container = document.getElementById('contract-parties-blocks');
            const blockId = 'party-' + Date.now() + Math.floor(Math.random() * 1000);
            const removeBtn = isRemovable ? `<button onclick="document.getElementById('${blockId}').remove()" class="absolute top-1 right-1 text-slate-400 hover:text-red-500 text-xs font-bold transition p-1 bg-slate-100 rounded opacity-0 group-hover:opacity-100">✕</button>` : '';
            const blockHTML = `
                <div class="relative party-block group bg-white p-3 rounded border border-slate-200 shadow-sm" id="${blockId}">
                    ${removeBtn}
                    <input type="text" placeholder="Role (e.g., Agency)" class="w-full text-xs font-bold mb-1 outline-none text-slate-500 uppercase tracking-wider party-role bg-transparent" value="${role}">
                    <input type="text" placeholder="Name / Business" class="w-full text-sm outline-none text-slate-900 font-medium party-name border-b border-dashed border-slate-300 focus:border-indigo-500 bg-transparent" value="${name}">
                </div>
            `;
            container.insertAdjacentHTML('beforeend', blockHTML);
        }
        // Add Dynamic Clause
        function addContractBlock(title = '', content = '') {
            const container = document.getElementById('contract-dynamic-blocks');
            const blockId = 'block-' + Date.now() + Math.floor(Math.random() * 1000);
            const blockHTML = `
                <div class="bg-white p-4 rounded-xl border border-slate-200 relative contract-block shadow-sm group" id="${blockId}">
                    <button onclick="document.getElementById('${blockId}').remove()" class="absolute top-2 right-2 text-slate-400 hover:text-red-500 text-xs font-bold transition p-1 bg-slate-100 rounded opacity-0 group-hover:opacity-100">Delete Block</button>
                    <input type="text" placeholder="Clause Title (e.g., INTELLECTUAL PROPERTY)" class="w-full font-bold mb-2 p-2 border-b border-slate-200 outline-none text-indigo-900 block-title" value="${title}">
                    <textarea placeholder="Clause details..." class="w-full h-24 p-2 text-sm text-slate-700 rounded outline-none resize-none block-content leading-relaxed">${content}</textarea>
                </div>
            `;
            container.insertAdjacentHTML('beforeend', blockHTML);
        }
        // Initialize Defaults
        function initDefaultContractStructure() {
            // Parties
            const partiesContainer = document.getElementById('contract-parties-blocks');
            partiesContainer.innerHTML = '';
            addPartyBlock('Contractor', '', false);
            addPartyBlock('Client', '', false);
            // Clauses
            const clausesContainer = document.getElementById('contract-dynamic-blocks');
            clausesContainer.innerHTML = '';
            addContractBlock('1. SERVICES RENDERED', 'The Contractor agrees to perform the services detailed in the Project Scope for the Client.');
            addContractBlock('2. OWNERSHIP & INTELLECTUAL PROPERTY', 'Upon final and full payment, the Contractor grants the Client full ownership and rights to the final deliverables. Preliminary drafts and source files remain the property of the Contractor.');
            addContractBlock('3. SCOPE CREEP & REVISIONS', 'Any requests falling outside the defined Services Rendered will be considered additional work and billed at a premium rate mutually agreed upon prior to commencement of extra work.');
            addContractBlock('4. TERMINATION', 'Either party may terminate this agreement with 14 days written notice. In the event of termination, the Client shall pay the Contractor for all work completed up to the date of termination.');
        }
        async function generateSecureContract() {
            const date = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
            let contractString = `INDEPENDENT CONTRACTOR AGREEMENT\n\nThis Agreement is entered into on ${date}, by and between:\n\n`;
            // Collect Parties
            const parties = document.querySelectorAll('.party-block');
            let signatureSection = `Signatures:\n\n`;
            parties.forEach((party) => {
                const role = party.querySelector('.party-role').value.trim() || 'Party';
                const name = party.querySelector('.party-name').value.trim() || '[Unspecified Name]';
                contractString += `${role}: ${name}\n`;
                signatureSection += `___________________________\n${name} (${role})\nDate: _________________\n\n`;
            });
            contractString += `\n`;
            // Metadata
            const scope = document.getElementById('contract-scope').value || '[Detailed Description of Deliverables]';
            const fee = document.getElementById('contract-fee').value || '[Total Fee Amount]';
            const terms = document.getElementById('contract-terms').value || '[Payment Terms]';
            contractString += `PROJECT SCOPE\n${scope}\n\nCOMPENSATION & PAYMENT SCHEDULE\nThe Client agrees to compensate the Contractor a total of ${fee}. Payments will be made according to the following schedule: ${terms}\n\n`;
            // Collect Clauses
            const blocks = document.querySelectorAll('.contract-block');
            blocks.forEach((block) => {
                const title = block.querySelector('.block-title').value.trim();
                const content = block.querySelector('.block-content').value.trim();
                if (title || content) {
                    contractString += `${title}\n${content}\n\n`;
                }
            });
            contractString += signatureSection;
            const outputArea = document.getElementById('contract-output-area');
            document.getElementById('contract-text').textContent = contractString;
            outputArea.classList.remove('hidden');
            // Generate Cryptography
            const encoder = new TextEncoder();
            const data = encoder.encode(contractString);
            try {
                const hashBuffer = await crypto.subtle.digest('SHA-256', data);
                const hashArray = Array.from(new Uint8Array(hashBuffer));
                const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
                document.getElementById('contract-hash').textContent = hashHex;
                window.currentContractHash = hashHex;
            } catch (err) {
                document.getElementById('contract-hash').textContent = "Cryptographic API requires a secure HTTPS environment.";
            }
        }
        // PDF Auto-Pagination & Formatting
        function downloadContractPDF() {
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const content = document.getElementById('contract-text').textContent;
            const hash = window.currentContractHash || "Hash unavailable";
            const includeHash = document.getElementById('pdf-include-hash').checked;
            doc.setFontSize(10);
            // Wrap text
            const splitText = doc.splitTextToSize(content, 180);
            let yPosition = 20;
            const pageHeight = doc.internal.pageSize.height;
            // Simple Pagination Loop
            for (let i = 0; i < splitText.length; i++) {
                if (yPosition > pageHeight - 30) {
                    doc.addPage();
                    yPosition = 20; // reset y for new page
                }
                doc.text(splitText[i], 15, yPosition);
                yPosition += 5; // increment line height
            }
            // Add ToolkitGen Branding and Optional Hash to the last page
            doc.setFont("helvetica", "normal");
            doc.setFontSize(8);
            doc.setTextColor(150);
            doc.text("Generated securely via ToolkitGen.com | OS for Freelancers & Creators", 15, pageHeight - 10);
            if (includeHash) {
                doc.setFont("courier", "bold");
                doc.setTextColor(100);
                doc.text(`Document SHA-256 Hash: ${hash}`, 15, pageHeight - 15);
            }
            doc.save("ToolkitGen_Agreement.pdf");
        }
        // --- Initialization and Global Event Binding ---
        function calculateAllTools() {
            calculateLTVCAC();
            calculateConcentrationRisk();
            calculatePPP();
            calculateScopeCreep();
            calculateAIRoi();
            calculateMeetingCost();
            calculateCreatorRevenue();
            calculateRate();
            calculateTaxes();
        }
        document.addEventListener('DOMContentLoaded', () => {
            document.getElementById('global-currency').addEventListener('change', calculateAllTools);
            ['ltv-avg-rev', 'ltv-projects', 'ltv-margin', 'ltv-current-cac'].forEach(id => document.getElementById(id).addEventListener('input', calculateLTVCAC));
            ['risk-total-rev', 'risk-top-client'].forEach(id => document.getElementById(id).addEventListener('input', calculateConcentrationRisk));
            document.getElementById('ppp-base-rate').addEventListener('input', calculatePPP);
            document.getElementById('ppp-client-region').addEventListener('change', calculatePPP);
            ['creep-fee', 'creep-est-hours', 'creep-act-hours'].forEach(id => document.getElementById(id).addEventListener('input', calculateScopeCreep));
            ['ai-rate', 'ai-cost', 'ai-hours', 'ai-gain'].forEach(id => document.getElementById(id).addEventListener('input', calculateAIRoi));
            ['meet-my-rate', 'meet-client-rate', 'meet-attendees', 'meet-duration'].forEach(id => document.getElementById(id).addEventListener('input', calculateMeetingCost));
            document.getElementById('creator-views').addEventListener('input', calculateCreatorRevenue);
            document.getElementById('creator-niche').addEventListener('change', calculateCreatorRevenue);
            document.getElementById('gig-amount').addEventListener('input', calculateTaxes);
            document.getElementById('tax-region').addEventListener('change', calculateTaxes);
            initDefaultContractStructure();
            calculateAllTools();
        });
